using System;
using System.IO;
using TrashAstronauts.Audio;
using UnityEditor;
using UnityEngine;

namespace TrashAstronauts.EditorTools
{
    /// <summary>
    /// Synthesizes every sound effect as a small mono WAV. Nothing is downloaded or licensed from a
    /// third party: all audio in the project is generated by this file and can be regenerated at will.
    /// </summary>
    public static partial class Builder
    {
        const int SampleRate = 22050;

        static void BuildAudio()
        {
            var lib = LoadOrCreate<AudioLibrary>(DataDir + "/AudioLibrary.asset", out _);
            var rng = new System.Random(4471);

            lib.grab = Wav("grab", 0.09f, (t, d) => Sine(150f, t) * Decay(t, 30f) * 0.8f + Noise(rng) * Decay(t, 60f) * 0.25f);
            lib.buttonClick = Wav("button_click", 0.07f, (t, d) => Noise(rng) * Decay(t, 180f) * 0.5f + Sine(880f, t) * Decay(t, 60f) * 0.5f);
            lib.deposit = Wav("deposit", 0.45f, (t, d) => (t < 0.15f ? Sine(660f, t) : Sine(880f, t)) * Env(t, d, 0.01f, 8f) * 0.6f);
            lib.depositJackpot = Wav("deposit_jackpot", 0.8f, (t, d) =>
            {
                float[] notes = { 523f, 659f, 784f, 1047f };
                int i = Mathf.Min(3, (int)(t / 0.14f));
                return (Sine(notes[i], t) + 0.3f * Sine(notes[i] * 2f, t)) * Env(t, d, 0.01f, 3f) * 0.5f;
            });
            lib.teleport = Wav("teleport", 0.18f, (t, d) => Noise(rng) * Mathf.Sin(Mathf.PI * t / d) * 0.35f + Sine(300f + 1500f * t / d, t) * Mathf.Sin(Mathf.PI * t / d) * 0.25f);
            lib.toolHolster = Wav("tool_holster", 0.1f, (t, d) => Noise(rng) * Decay(t, 90f) * 0.5f + Sine(240f, t) * Decay(t, 45f) * 0.6f);
            lib.flashlightClick = Wav("flashlight_click", 0.04f, (t, d) => Noise(rng) * Decay(t, 250f) * 0.7f);
            lib.scannerPing = Wav("scanner_ping", 0.3f, (t, d) => Sine(1200f + 900f * t / d, t) * Env(t, d, 0.005f, 9f) * 0.5f);
            lib.scannerHit = Wav("scanner_hit", 0.22f, (t, d) => Sine(1568f, t) * (Decay(t, 40f) + (t > 0.1f ? Decay(t - 0.1f, 40f) : 0f)) * 0.5f);
            lib.cutterLoop = Wav("cutter_loop", 1.0f, (t, d) => (Saw(90f, t) * 0.35f + Noise(rng) * 0.3f) * (0.8f + 0.2f * Sine(8f, t)), true);
            lib.cutterSparks = Wav("cutter_sparks", 0.14f, (t, d) => Noise(rng) * (rng.NextDouble() < 0.4 ? 1f : 0.1f) * Decay(t, 22f) * 0.7f);
            lib.cutterOverheat = Wav("cutter_overheat", 0.7f, (t, d) => Square(900f - 500f * t / d, t) * (Mathf.Repeat(t, 0.23f) < 0.14f ? 1f : 0f) * 0.3f);
            lib.panelBreak = Wav("panel_break", 0.8f, (t, d) => (Sine(310f, t) + Sine(487f, t) * 0.7f + Sine(923f, t) * 0.5f) * Decay(t, 6f) * 0.3f + Noise(rng) * Decay(t, 25f) * 0.5f);
            lib.impactLight = Wav("impact_light", 0.18f, (t, d) => (Sine(620f, t) + Sine(1130f, t) * 0.6f) * Decay(t, 35f) * 0.4f + Noise(rng) * Decay(t, 90f) * 0.35f);
            lib.impactHeavy = Wav("impact_heavy", 0.4f, (t, d) => (Sine(140f, t) + Sine(233f, t) * 0.7f + Sine(410f, t) * 0.4f) * Decay(t, 12f) * 0.45f + Noise(rng) * Decay(t, 50f) * 0.4f);
            lib.doorMove = Wav("door_move", 1.1f, (t, d) => (Saw(60f - 15f * t / d, t) * 0.3f + Noise(rng) * 0.12f) * Env(t, d, 0.05f, 1.2f));
            lib.airlockHiss = Wav("airlock_hiss", 1.5f, (t, d) => Noise(rng) * Env(t, d, 0.03f, 2.5f) * 0.45f + Saw(55f, t) * Env(t, d, 0.1f, 2f) * 0.15f);
            lib.shipAmbience = Wav("ship_ambience", 4.0f, (t, d) => Sine(55f, t) * 0.3f + Sine(82.5f, t) * 0.18f * (0.6f + 0.4f * Sine(0.25f, t)) + Sine(110.25f, t) * 0.08f + Noise(rng) * 0.02f, true);
            lib.tugAmbience = Wav("tug_ambience", 3.0f, (t, d) => Sine(110f, t) * 0.12f + Sine(220f, t) * 0.04f + Noise(rng) * 0.035f, true);
            lib.oxygenLow = Wav("oxygen_low", 0.6f, (t, d) => Sine(700f, t) * ((t < 0.18f || (t > 0.3f && t < 0.48f)) ? 1f : 0f) * 0.4f);
            lib.oxygenCritical = Wav("oxygen_critical", 0.5f, (t, d) => Square(1000f, t) * (Mathf.Repeat(t, 0.16f) < 0.08f ? 1f : 0f) * 0.25f);
            // The creature: a wet, uneven breathing growl with irregular clicks instead of a machine hum.
            float lpA = 0f, lpB = 0f;
            lib.droneHum = Wav("drone_hum", 2.0f, (t, d) =>
            {
                lpA += (Noise(rng) - lpA) * 0.06f;
                float breath = 0.5f + 0.5f * Sine(1f, t);
                float click = Mathf.Repeat(t * 7.3f + 0.4f * Sine(0.5f, t), 1f) < 0.035f ? Noise(rng) * 0.5f : 0f;
                return lpA * 2.2f * (0.35f + 0.65f * breath) + Saw(38f, t) * 0.16f * breath + Sine(57f, t) * 0.12f + click * 0.5f;
            }, true);
            lib.droneAlert = Wav("drone_alert", 0.7f, (t, d) =>
            {
                float f = 240f + 1100f * Mathf.Pow(t / d, 2.2f);
                return (Sine(f + 90f * Sine(31f, t), t) * 0.45f + Noise(rng) * 0.18f * (t / d)) * Env(t, d, 0.02f, 1.6f);
            });
            lib.droneChase = Wav("drone_chase", 1.0f, (t, d) =>
            {
                lpB += (Noise(rng) - lpB) * 0.25f;
                float pulse = 0.55f + 0.45f * Sine(9f, t);
                return (Saw(64f, t) * 0.3f + Sine(520f + 260f * Sine(13f, t), t) * 0.22f + lpB * 0.9f) * pulse * 0.75f;
            }, true);
            lib.droneLost = Wav("drone_lost", 1.0f, (t, d) => (Saw(210f - 150f * t / d, t) * 0.3f + Sine(105f - 60f * t / d, t) * 0.35f) * Env(t, d, 0.03f, 1.8f)
                + (Mathf.Repeat(t * 11f, 1f) < 0.05f ? Noise(rng) * 0.25f : 0f) * (1f - t / d));
            lib.droneCatch = Wav("drone_catch", 0.8f, (t, d) => (Saw(140f - 90f * t / d, t) * 0.5f + Noise(rng) * 0.5f + Sine(900f - 700f * t / d, t) * 0.25f) * Env(t, d, 0.004f, 3f));
            lib.resultSuccess = Wav("result_success", 1.2f, (t, d) =>
            {
                float[] notes = { 392f, 494f, 587f, 784f };
                int i = Mathf.Min(3, (int)(t / 0.2f));
                return (Sine(notes[i], t) + 0.25f * Sine(notes[i] * 2f, t)) * Env(t, d, 0.01f, 2f) * 0.45f;
            });
            lib.resultPartial = Wav("result_partial", 0.8f, (t, d) => (t < 0.3f ? Sine(440f, t) : Sine(392f, t)) * Env(t, d, 0.01f, 3f) * 0.45f);
            lib.resultFail = Wav("result_fail", 1.2f, (t, d) =>
            {
                float[] notes = { 392f, 349f, 311f, 233f };
                int i = Mathf.Min(3, (int)(t / 0.25f));
                return (Sine(notes[i], t) + 0.3f * Saw(notes[i] * 0.5f, t)) * Env(t, d, 0.01f, 1.5f) * 0.4f;
            });

            EditorUtility.SetDirty(lib);
            AssetDatabase.SaveAssets();
        }

        static float Sine(float hz, float t) => Mathf.Sin(2f * Mathf.PI * hz * t);
        static float Saw(float hz, float t) => 2f * Mathf.Repeat(hz * t, 1f) - 1f;
        static float Square(float hz, float t) => Mathf.Repeat(hz * t, 1f) < 0.5f ? 1f : -1f;
        static float Noise(System.Random rng) => (float)(rng.NextDouble() * 2.0 - 1.0);
        static float Decay(float t, float rate) => Mathf.Exp(-rate * Mathf.Max(0f, t));
        static float Env(float t, float d, float attack, float decayRate) =>
            Mathf.Clamp01(t / attack) * Mathf.Exp(-decayRate * t) * Mathf.Clamp01((d - t) / 0.02f);

        static AudioClip Wav(string name, float seconds, Func<float, float, float> sample, bool loop = false)
        {
            int count = Mathf.RoundToInt(seconds * SampleRate);
            var data = new float[count];
            for (int i = 0; i < count; i++) data[i] = sample(i / (float)SampleRate, seconds);

            if (loop)
            {
                // Crossfade the tail into the head so the loop point is click-free.
                int fade = Mathf.Min(count / 4, SampleRate / 10);
                for (int i = 0; i < fade; i++)
                {
                    float k = i / (float)fade;
                    data[i] = data[i] * k + data[count - fade + i] * (1f - k);
                }
                count -= fade;
            }
            else
            {
                int fade = Mathf.Min(count, 64);
                for (int i = 0; i < fade; i++) data[count - 1 - i] *= i / (float)fade;
            }

            string path = AudioDir + "/" + name + ".wav";
            using (var stream = new FileStream(path, FileMode.Create))
            using (var writer = new BinaryWriter(stream))
            {
                int bytes = count * 2;
                writer.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));
                writer.Write(36 + bytes);
                writer.Write(System.Text.Encoding.ASCII.GetBytes("WAVE"));
                writer.Write(System.Text.Encoding.ASCII.GetBytes("fmt "));
                writer.Write(16);
                writer.Write((short)1);
                writer.Write((short)1);
                writer.Write(SampleRate);
                writer.Write(SampleRate * 2);
                writer.Write((short)2);
                writer.Write((short)16);
                writer.Write(System.Text.Encoding.ASCII.GetBytes("data"));
                writer.Write(bytes);
                for (int i = 0; i < count; i++)
                    writer.Write((short)Mathf.RoundToInt(Mathf.Clamp(data[i], -1f, 1f) * 32000f));
            }

            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);
            return AssetDatabase.LoadAssetAtPath<AudioClip>(path);
        }
    }
}
